{
  "name": "opencode-tmux-status",
  "version": "0.1.0",
  "description": "OpenCode plugin that syncs session state to tmux window options.",
  "packageManager": "bun@1.3.10",
  "type": "module",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/AksharP5/opencode-tmux-status.git"
  },
  "homepage": "https://github.com/AksharP5/opencode-tmux-status#readme",
  "bugs": {
    "url": "https://github.com/AksharP5/opencode-tmux-status/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tmux",
    "status"
  ],
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "typecheck": "tsc --noEmit -p tsconfig.json",
    "prepublishOnly": "bun run typecheck && bun run build"
  },
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@opencode-ai/plugin": "1.2.20"
  },
  "devDependencies": {
    "@types/node": "22.13.9",
    "typescript": "5.8.2"
  },
  "engines": {
    "node": ">=20"
  }
}
